\set ON_ERROR_STOP on
SELECT jsonb_pretty(jsonb_build_object(
 'captured_at',clock_timestamp(),'database',current_database(),'version',version(),'socket',inet_server_addr() IS NULL,
 'routines',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'schema',n.nspname,'name',p.proname,'source',p.prosrc,'definition',pg_get_functiondef(p.oid),'acl',p.proacl,'owner',pg_get_userbyid(p.proowner),'source_md5',md5(p.prosrc)) ORDER BY n.nspname,p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private','auth') AND p.proname IN ('reserve_ai_quota_for_user','check_ai_quotas_for_user','get_ai_call_monthly_limit','get_ai_call_monthly_base_limit','check_ai_call_monthly_limit_trigger','get_available_addon_credits','get_addon_credit_balance','consume_addon_credit_for_user','current_billing_runtime_mode','addon_credit_bucket','addon_credit_units','set_addon_purchase_credits','touch_addon_purchases_updated_at','has_platform_admin','authoritative_role','is_pro','has_free_ai_access_for_user','has_current_billing_subscription_for_user','current_billing_subscription_for_user','has_investor_subscription_for_user','profile_pricing_audience','uid','role','handle_new_user','auto_grant_owner_privileges','sync_profiles_public','complete_onboarding_role_for_user','unarchive_role_data','profiles_guard_admin_and_role','guard_sensitive_profile_columns','update_updated_at_column')),
 'relations',(SELECT jsonb_agg(jsonb_build_object('name',c.oid::regclass::text,'acl',c.relacl,'rls',c.relrowsecurity,'constraints',(SELECT jsonb_agg(pg_get_constraintdef(oid)) FROM pg_constraint WHERE conrelid=c.oid),'triggers',(SELECT jsonb_agg(jsonb_build_object('name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid))) FROM pg_trigger WHERE tgrelid=c.oid AND NOT tgisinternal))) FROM pg_class c WHERE c.oid IN ('public.addon_purchases'::regclass,'public.usage_ai_calls'::regclass,'public.ai_usage_limits'::regclass,'public.profiles'::regclass,'auth.users'::regclass)),
 'limit',(SELECT row_to_json(l) FROM public.ai_usage_limits l WHERE bucket='property-valuation'),
 'service_acl',jsonb_build_object('reserve',has_function_privilege('service_role','public.reserve_ai_quota_for_user(uuid,text)','EXECUTE'),'batch',has_function_privilege('service_role','public.check_ai_quotas_for_user(uuid,text[])','EXECUTE'))
));
